@Configuration
@EnableWebSecurity
public class RestApiSecurityConfig {

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        http
            .csrf(csrf -> csrf.disable())  // typically disabled for stateless REST
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/api/public/**").permitAll()
                .requestMatchers("/api/**").authenticated()
            )
            .formLogin(form -> form
                .loginProcessingUrl("/api/login")  // POST endpoint for credentials
                .successHandler(authSuccessHandler())
                .failureHandler(authFailureHandler())
            )
            .sessionManagement(session -> session
                .sessionCreationPolicy(SessionCreationPolicy.IF_REQUIRED)
            );
        return http.build();
    }

    private AuthenticationSuccessHandler authSuccessHandler() {
        return (request, response, authentication) -> {
            response.setStatus(HttpServletResponse.SC_OK);
            response.setContentType("application/json");
            var user = (UserDetails) authentication.getPrincipal();
            var json = String.format(
                "{\"username\":\"%s\",\"authorities\":%s}",
                user.getUsername(),
                authentication.getAuthorities().stream()
                    .map(a -> "\"" + a.getAuthority() + "\"")
                    .collect(Collectors.joining(",", "[", "]"))
            );
            response.getWriter().write(json);  // return user data as JSON
        };
    }

    private AuthenticationFailureHandler authFailureHandler() {
        return (request, response, exception) -> {
            response.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
            response.setContentType("application/json");
            response.getWriter().write(
                "{\"error\":\"Authentication failed\",\"message\":\"" 
                + exception.getMessage() + "\"}"
            );
        };
    }
}

@Configuration
@EnableWebSecurity
public class SecurityConfig {

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        http
            .authorizeHttpRequests(auth -> auth.anyRequest().authenticated())
            .formLogin(form -> form
                .loginPage("/login")
                .failureHandler(authenticationFailureHandler())
                .permitAll()
            );
        return http.build();
    }

    @Bean
    public AuthenticationFailureHandler authenticationFailureHandler() {
        return (request, response, exception) -> {
            var errorMessage = "Authentication failed";
            var httpStatus = HttpServletResponse.SC_UNAUTHORIZED;

            // Don't reveal specific failure reasons to prevent user enumeration
            if (exception instanceof BadCredentialsException) {
                errorMessage = "Invalid username or password";  // generic message
            } else if (exception instanceof LockedException) {
                errorMessage = "Account is locked. Contact support.";
                httpStatus = HttpServletResponse.SC_FORBIDDEN;
            } else if (exception instanceof DisabledException) {
                errorMessage = "Account is disabled. Contact support.";
                httpStatus = HttpServletResponse.SC_FORBIDDEN;
            }

            // For REST API: return JSON
            response.setStatus(httpStatus);
            response.setContentType("application/json");
            response.getWriter().write(
                String.format("{\"error\":\"%s\",\"timestamp\":\"%s\"}",
                    errorMessage, Instant.now())
            );

            // For traditional web app, you'd redirect instead:
            // response.sendRedirect("/login?error=" + URLEncoder.encode(errorMessage));
        };
    }
}

@Configuration
@EnableWebSecurity
public class SecurityConfig {

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/public/**").permitAll()
                .anyRequest().authenticated()
            )
            .formLogin(Customizer.withDefaults())
            .logout(logout -> logout
                .logoutUrl("/api/logout")  // Custom logout URL
                .invalidateHttpSession(true)  // Destroy session
                .deleteCookies("JSESSIONID", "remember-me")  // Remove cookies
                .clearAuthentication(true)  // Clear SecurityContext
                .logoutSuccessHandler((request, response, auth) -> {
                    response.setStatus(HttpStatus.OK.value());
                    response.getWriter().write("{\"message\":\"Logged out successfully\"}");
                })
            );
        return http.build();
    }
}

