@Configuration
@EnableWebSecurity
public class SecurityConfig {

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        http
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/public/**").permitAll()
                .anyRequest().authenticated()
            )
            .formLogin(form -> form
                .loginPage("/login")           // custom login page URL
                .loginProcessingUrl("/authenticate")  // where form posts to
                .defaultSuccessUrl("/dashboard")
                .failureUrl("/login?error=true")
                .permitAll()
            );
        return http.build();
    }

    @Bean
    public UserDetailsService userDetailsService(UserRepository userRepo) {
        return username -> userRepo.findByUsername(username)
            .map(user -> User.builder()  // Spring Security User
                .username(user.getUsername())
                .password(user.getPasswordHash())
                .authorities(user.getRoles())
                .accountLocked(user.isLocked())
                .build())
            .orElseThrow(() -> new UsernameNotFoundException("User not found"));
    }

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder();  // injected into DaoAuthenticationProvider
    }
}

@Component
public class JwtAuthenticationFilter extends OncePerRequestFilter {

    private final JwtTokenProvider jwtProvider;

    @Override
    protected void doFilterInternal(HttpServletRequest request,
                                    HttpServletResponse response,
                                    FilterChain filterChain) throws ServletException, IOException {
        var token = extractTokenFromHeader(request);

        if (token != null && jwtProvider.validateToken(token)) {
            var username = jwtProvider.getUsernameFromToken(token);
            var authorities = jwtProvider.getAuthoritiesFromToken(token);

            // Create authenticated token directly, bypassing password check
            var authToken = new UsernamePasswordAuthenticationToken(
                username,        // principal: the authenticated user identifier
                null,           // credentials: null after authentication for security
                authorities     // authorities: roles/permissions from JWT claims
            );

            // Store in SecurityContext for this request
            SecurityContextHolder.getContext().setAuthentication(authToken);
        }

        filterChain.doFilter(request, response);
    }

    private String extractTokenFromHeader(HttpServletRequest request) {
        var header = request.getHeader("Authorization");
        if (header != null && header.startsWith("Bearer ")) {
            return header.substring(7);  // strip "Bearer " prefix
        }
        return null;
    }
}
